import styled from 'styled-components';

import { DEFAULT_ALL_TAB } from '@enterprise/context/SearchMenu/SearchResultsContext';

import { EmptyAllProviderSearchContainer } from './EmptyAllProviderSearchContainer';
import EmptySingleProviderSearchContainer from './EmptySingleProviderSearchContainer';

export const EMPTY_SEARCH_INPUT_CONTAINER_ID = 'empty-search-input-container';

export const EmptySearchInputContainer = ({
    showQuerylessText,
    providerId
}: {
    showQuerylessText: boolean;
    providerId: string;
}) => {
    return showQuerylessText && providerId !== DEFAULT_ALL_TAB.id ? (
        <EmptySingleProviderSearchContainer providerId={providerId} />
    ) : (
        <EmptyAllProviderSearchContainer />
    );
};

// shared between the EmptyAllProviderSearchContainer and EmptySingleProviderSearchContainer components
export const ContentContainer = styled.div`
    padding-top: ${({ theme }) => theme.px.base};
    padding-bottom: ${({ theme }) => theme.px.large};
    padding-left: ${({ theme }) => theme.px.xxlarge};
    padding-right: ${({ theme }) => theme.px.xxlarge};

    border-left: 1px solid var(--color-enterprise-search-menu-border);
    border-right: 1px solid var(--color-enterprise-search-menu-border);

    overflow-y: auto;
    overflow-x: hidden;
    ::-webkit-scrollbar {
        display: none;
    }
`;
