import { Fragment, useContext, useRef, useState } from 'react';

import styled from 'styled-components';

import { Box, Text } from '@openfin/ui-library';

import { raiseBrowserAnalytics } from '@common/utils/usage-register';

import { t } from '@common/api/i18next';

import { SearchMenuControlContext } from '@enterprise/context/SearchMenu/SearchMenuControlContext';
import { SearchResultsContext } from '@enterprise/context/SearchMenu/SearchResultsContext';

import { ContentContainer, EMPTY_SEARCH_INPUT_CONTAINER_ID } from './EmptySearchInputContainer';
import { RecentSite } from './RecentSite';
import { SiteCard } from './SiteCard';

const CURATED_CONTENT_LIMIT = 15;
const RECENT_CONTENT_LIMIT = 5;

export const EmptyAllProviderSearchContainer = () => {
    const { recentlyVisited, curatedContent } = useContext(SearchResultsContext);
    const { setSelectedSite, sendKeyboardEventToBrowserWindow } = useContext(SearchMenuControlContext);

    const [selectedFeaturedSite, setSelectedFeaturedSite] = useState(-1);
    const [selectedRecentlyVisited, setSelectedRecentlyVisited] = useState(-1);
    const featuredListContainer = useRef(null);

    const onSelectedFeaturedSite = (index: number) => {
        const curatedContentItem = curatedContent[index];

        raiseBrowserAnalytics({
            action: 'Select Featured Item',
            type: 'Search',
            value: curatedContentItem.title,
            data: { uuid: curatedContentItem.id }
        });

        setSelectedFeaturedSite(index);
        setSelectedSite(curatedContent[index]);
    };

    const onSelectedRecentlyVisited = (index: number) => {
        const recentlyVisitedItem = recentlyVisited[index];

        raiseBrowserAnalytics({
            action: 'Select Recently Visited Item',
            type: 'Search',
            value: recentlyVisitedItem.title,
            data: { uuid: recentlyVisitedItem.id }
        });

        setSelectedRecentlyVisited(index);
        setSelectedSite(recentlyVisited[index]);
    };

    return (
        <div id={EMPTY_SEARCH_INPUT_CONTAINER_ID}>
            <ContentContainer>
                {curatedContent.length > 0 && (
                    <>
                        <Title size="xxlarge" weight="bold">
                            {t('appResults.header')}
                        </Title>

                        <EmptySearchInputWrapper role="listbox" ref={featuredListContainer}>
                            {curatedContent?.slice(0, CURATED_CONTENT_LIMIT).map((site, index) => {
                                return (
                                    <Fragment key={`curated-content-${site.id}`}>
                                        <SiteCard
                                            id={`curatedContent-${index}`}
                                            site={site}
                                            index={index}
                                            isSelected={selectedFeaturedSite === index}
                                            onSelectedSite={onSelectedFeaturedSite}
                                            sendKeyboardEventToBrowserWindow={sendKeyboardEventToBrowserWindow}
                                        />
                                    </Fragment>
                                );
                            })}
                        </EmptySearchInputWrapper>
                    </>
                )}
                <Title size="xxlarge" weight="bold">
                    {t('recentlyClosed.header')}
                </Title>
                {recentlyVisited.length ? (
                    <RecentSiteContainer>
                        {recentlyVisited.slice(0, RECENT_CONTENT_LIMIT).map((site, index) => {
                            return (
                                <Fragment key={`recent-site-${index}`}>
                                    <RecentSite
                                        id={recentlyVisited[index].id}
                                        site={site}
                                        index={index}
                                        isSelected={selectedRecentlyVisited === index}
                                        onSelectedSite={onSelectedRecentlyVisited}
                                        sendKeyboardEventToBrowserWindow={sendKeyboardEventToBrowserWindow}
                                    />
                                </Fragment>
                            );
                        })}
                    </RecentSiteContainer>
                ) : (
                    <NoRecentlyVisited>
                        <NoRecentlyVisitedText className="search-no-recently-visited-text">
                            Recently visited content appears here when you explore or search.
                        </NoRecentlyVisitedText>
                    </NoRecentlyVisited>
                )}
            </ContentContainer>
            <BottomBorder className="search-empty-bottom-border" />
        </div>
    );
};

export const EMPTY_SEARCH_INPUT_CONTAINER_BORDER_HEIGHT = 1;

const Title = styled(Text)`
    line-height: ${({ theme }) => theme.px.xxlarge};
    margin: 0 0 ${({ theme }) => theme.px.base};
    font-size: ${({ theme }) => theme.px.large};
    font-weight: 600;
    display: block;
`;

const breakpoints = {
    min: 376,
    max: 728
};

const EmptySearchInputWrapper = styled.div`
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(64px, 1fr));
    max-width: 680px;
    max-height: 192px;
    overflow: auto;
    gap: ${({ theme }) => theme.px.large};
    margin-bottom: ${({ theme }) => theme.px.xxlarge};
    padding-right: ${({ theme }) => theme.px.base};
    @media (min-width: ${breakpoints.min}) and (max-width: ${breakpoints.max}) {
        grid-template-columns: repeat(auto-fill, minmax(64px, calc((100% - 48px) / 4)));
    }
    @media (min-width: ${breakpoints.max}) {
        grid-template-columns: repeat(auto-fill, minmax(64px, calc((100% - 112px) / 8)));
    }

    /* SiteCard handles its own hover/focus styling internally */
`;

const RecentSiteContainer = styled(Box)`
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    justify-content: center;
    padding-left: ${({ theme }) => theme.px.xsmall};
    outline: none;

    /* Outline and background colors handled by .enterprise-search__result */
`;

const NoRecentlyVisited = styled.div`
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    justify-content: center;
    margin-top: ${({ theme }) => theme.px.base};
`;

const NoRecentlyVisitedText = styled.span`
    color: var(--color-enterprise-search-menu-text-base);
    font-size: 12px;
    line-height: 16px;
    font-weight: 400;
`;

const BottomBorder = styled.div`
    height: ${EMPTY_SEARCH_INPUT_CONTAINER_BORDER_HEIGHT}px;
    width: 100%;
    background-color: var(--color-role-background-5);
    z-index: 1;
    position: sticky;
    bottom: 0;
    left: 0;
    right: 0;
`;
