import { Dispatch, SetStateAction, useCallback, useContext, useEffect, useMemo, useRef, useState } from 'react';
import { useSelector } from 'react-redux';

import type OpenFin from '@openfin/core';

import debounce from 'lodash.debounce';

import { SearchMenuChannelMessage, SearchMenuChannelResponse } from '@common/utils/popup-window';
import { raiseBrowserAnalytics } from '@common/utils/usage-register';
import { randomUUID } from '@common/utils/uuid';
import { WindowName } from '@common/utils/window';

import { selectIsWindows } from '@common/slices/environment';

import { ActionedSite } from '@client-platform/index';
import { DEFAULT_ALL_TAB, SearchResultsContext } from '@enterprise/context/SearchMenu/SearchResultsContext';
import { SearchViewExpansionState } from '@enterprise/context/SearchMenu/WindowSearchMenuContext';
import { getSearchProviders, searchSites } from '@enterprise/hooks/EnterpriseSearchMenu/utils';

export const SEARCH_DEBOUNCE_MS = 500;

/**
 * Custom hook that initializes and manages search functionality and expansion state for the search menu view.
 * It handles communication from the browser window to the search menu view.
 *
 * @param {boolean} shouldExpand - Boolean indicating if the search results view should expand.
 * @param {Dispatch<SetStateAction<number>>} setFocusRequestId - Function to update the focus request ID.
 * @param {Dispatch<SetStateAction<SearchViewExpansionState>>} setShouldExpandMenu - Function to update the expansion state of the search menu.
 * @param {Dispatch<SetStateAction<boolean>>} setShouldShowEmptySearchContainer - Function to toggle the empty search container visibility.
 * @param {Dispatch<SetStateAction<number>>} setOffsetLeft - Function to update the left offset of the search menu.
 * @param {Dispatch<SetStateAction<ActionedSite | undefined>>} setSelectedSite - Function to update the selected site.
 * @returns {Object} An object containing:
 *   - searchMenuChannel: Reference to the BroadcastChannel used for communication
 *   - selectedViews: Array of currently selected OpenFin views
 *   - openViews: Array of currently open OpenFin views
 *   - queryId: Current query identifier
 *   - updateSearchResults: Function to trigger a search with optional debouncing
 *     Parameters: ({ query, providerId, shouldExpandMenu?, immediate?, searchFilters })
 *     When immediate is true, the search executes without debouncing
 *   - searchQuery: Reference to the current search query
 *   - hasTextChangedSinceExpansion: Boolean indicating whether user has modified the URL since search menu expanded
 */
const useInitChannelToBrowserWindow = (
    shouldExpand: boolean,
    setFocusRequestId: Dispatch<SetStateAction<number>>,
    setShouldExpandMenu: Dispatch<SetStateAction<SearchViewExpansionState>>,
    setShouldShowEmptySearchContainer: Dispatch<SetStateAction<boolean>>,
    setOffsetLeft: Dispatch<SetStateAction<number>>,
    setSelectedSite: Dispatch<SetStateAction<ActionedSite | undefined>>
) => {
    const {
        setSearchResults,
        setIsQueryingResults,
        activeProviderId,
        setActiveProviderId,
        searchProviders,
        setSearchProviders,
        filters
    } = useContext(SearchResultsContext);

    const isWindows = useSelector(selectIsWindows);
    const searchMenuChannel = useRef<BroadcastChannel>();

    const [selectedViews, setSelectedViews] = useState<OpenFin.Identity[]>([]);
    const [openViews, setOpenViews] = useState<OpenFin.Identity[]>([]);
    const [queryId, setQueryId] = useState<string>();

    const hasFetchedSearchProviders = useRef<boolean>(false);
    const mostRecentUpdateId = useRef<number>();
    const searchQuery = useRef<string>('');
    const hasTextChangedSinceExpansion = useRef<boolean>(false);

    const executeSearch = useCallback(
        async (query: string, newQueryId: string, requestId: number, providerId?: string, searchFilters?: string[]) => {
            raiseBrowserAnalytics({
                type: 'Search',
                action: 'Run Search'
            });
            const sites = await searchSites({
                query: query.trim(),
                queryId: newQueryId,
                providerId,
                filters: searchFilters
            });

            if (requestId === mostRecentUpdateId.current) {
                setSearchResults(sites);
                setShouldShowEmptySearchContainer(false);
            }

            setIsQueryingResults(false);
        },
        [setSearchResults, setShouldShowEmptySearchContainer, setIsQueryingResults]
    );

    const debouncedExecuteSearch = useMemo(
        () => debounce(executeSearch, SEARCH_DEBOUNCE_MS, { leading: false, trailing: true }),
        [executeSearch]
    );

    const updateSearchResults = useCallback(
        async ({
            query,
            providerId,
            shouldExpandMenu,
            immediate = false,
            searchFilters
        }: {
            query: string;
            providerId: string;
            shouldExpandMenu?: SearchViewExpansionState;
            immediate?: boolean;
            searchFilters: string[];
        }) => {
            setIsQueryingResults(true);

            // Cancel any pending debounced calls
            debouncedExecuteSearch.cancel();

            const requestId = Date.now();
            mostRecentUpdateId.current = requestId;
            const newQueryId = randomUUID();
            setQueryId(newQueryId);
            setSearchResults([]);
            const provider = searchProviders.find((p) => p.id === providerId);

            // For providers not supporting queryless, only search if query isn't empty
            // and user has modified the text.

            // For providers supporting queryless, only search if query is empty
            // or if the user has modified the search text.

            // This prevents an unwanted search of the selected view's URL
            // when first expanding the menu and clicking on a provider tab.

            const shouldSearchProviderSupportingQueryless =
                !provider?.supportsQueryless && query.length > 0 && hasTextChangedSinceExpansion.current;
            const shouldSearchProviderWithoutQueryless =
                provider?.supportsQueryless && (query.length === 0 || hasTextChangedSinceExpansion.current);

            if (shouldSearchProviderSupportingQueryless || shouldSearchProviderWithoutQueryless) {
                setShouldShowEmptySearchContainer(false);
                if (immediate) {
                    await executeSearch(query, newQueryId, requestId, providerId, searchFilters);
                } else {
                    await debouncedExecuteSearch(query, newQueryId, requestId, providerId, searchFilters);
                }
            } else {
                setShouldShowEmptySearchContainer(providerId === DEFAULT_ALL_TAB.id ? true : false);
                setIsQueryingResults(false);
            }

            // Only update shouldExpandMenu if this is the most recent request
            if (shouldExpandMenu && requestId === mostRecentUpdateId.current) {
                setShouldExpandMenu(shouldExpandMenu);
            }
        },
        // eslint-disable-next-line react-hooks/exhaustive-deps
        [searchProviders, debouncedExecuteSearch, executeSearch]
    );

    const handleSearchMenuMessage = useCallback(
        async (ev: MessageEvent<SearchMenuChannelMessage>) => {
            switch (ev.data.type) {
                case 'ready':
                    // View sends a "ready" message to the browser window by default immediately after initialization.
                    // However, in case the view is initialized before the browser window's message handler is set up,
                    // the browser window will send a "ready" message itself, and the view should respond with another
                    // "ready" to complete a handshake, indicating both the browser and view can receive messages.
                    searchMenuChannel.current.postMessage({ type: 'ready' } as SearchMenuChannelResponse);
                    break;
                case 'update-search-menu-state': {
                    const shouldUpdateSelectedViews =
                        (ev.data.selectedViews !== undefined &&
                            selectedViews?.length !== ev.data.selectedViews.length) ||
                        ev.data.selectedViews?.every((view) =>
                            selectedViews.some(
                                (selectedView) =>
                                    !(selectedView?.name === view?.name && selectedView?.uuid === view?.uuid)
                            )
                        );

                    const shouldUpdateOpenViews =
                        (ev.data.openViews !== undefined && openViews?.length !== ev.data.openViews.length) ||
                        ev.data.openViews?.every((view) =>
                            openViews.some((openView) => !(openView.name === view.name && openView.uuid === view.uuid))
                        );

                    const shouldEmitKeyboardEvent = ev.data.keyboardEvent?.options !== undefined;

                    // Process expand state changes, and always process click/keystroke methods to ensure view is brought to front when already expanded
                    const shouldUpdateShouldExpandMenu =
                        ev.data.shouldExpandMenu !== undefined &&
                        (ev.data.shouldExpandMenu.shouldExpand !== shouldExpand ||
                            ev.data.shouldExpandMenu.method !== undefined);

                    const shouldUpdateSearchText =
                        ev.data.searchText !== undefined && ev.data.shouldExpandMenu.shouldExpand;

                    if (shouldUpdateSearchText) {
                        if (searchQuery.current !== ev.data.searchText) {
                            hasTextChangedSinceExpansion.current = shouldExpand;
                        }
                        searchQuery.current = ev.data.searchText;
                    }

                    if (shouldUpdateSelectedViews) {
                        setSelectedViews(ev.data.selectedViews);
                    }
                    if (shouldUpdateOpenViews) {
                        setOpenViews(ev.data.openViews);
                    }

                    if (!hasFetchedSearchProviders.current && ev.data.shouldExpandMenu?.shouldExpand) {
                        hasFetchedSearchProviders.current = true;
                        const providers = await getSearchProviders();
                        setSearchProviders(providers);
                    }

                    if (shouldUpdateShouldExpandMenu) {
                        setOffsetLeft(ev.data.offsetLeft);

                        if (!ev.data.shouldExpandMenu.shouldExpand) {
                            mostRecentUpdateId.current = Date.now();

                            // Hide search menu and reset state
                            setShouldExpandMenu(ev.data.shouldExpandMenu);
                            (fin.me as OpenFin.View).hide();
                            setActiveProviderId(DEFAULT_ALL_TAB.id);
                            setSelectedSite(undefined);
                        }

                        if (ev.data.shouldExpandMenu.method === 'click') {
                            mostRecentUpdateId.current = Date.now();
                            setShouldShowEmptySearchContainer(true);
                            setShouldExpandMenu(ev.data.shouldExpandMenu);
                            updateSearchResults({
                                query: searchQuery.current,
                                providerId: activeProviderId,
                                shouldExpandMenu: ev.data.shouldExpandMenu,
                                searchFilters: filters
                            });

                            // Ensure search menu is brought to front so that it is not hidden behind the content view
                            if (shouldExpand) {
                                await fin.me.bringToFront();
                            }
                        }

                        if (ev.data.shouldExpandMenu.method === 'keystroke') {
                            hasTextChangedSinceExpansion.current = true;
                            updateSearchResults({
                                query: searchQuery.current,
                                providerId: activeProviderId,
                                shouldExpandMenu: ev.data.shouldExpandMenu,
                                searchFilters: filters
                            });
                        }
                    } else if (shouldUpdateSearchText) {
                        setSearchResults([]);
                        updateSearchResults({
                            query: searchQuery.current,
                            providerId: activeProviderId,
                            shouldExpandMenu: ev.data.shouldExpandMenu,
                            immediate: false,
                            searchFilters: filters
                        });
                    }

                    if (shouldEmitKeyboardEvent) {
                        if (ev.data.keyboardEvent.options.key === 'Tab') {
                            // Indicates a new focus switch from the address input to the search view
                            setFocusRequestId(Date.now());
                        } else if (ev.data.keyboardEvent.options.key === 'Enter') {
                            document.dispatchEvent(
                                new KeyboardEvent(ev.data.keyboardEvent.type, ev.data.keyboardEvent.options)
                            );
                        } else {
                            window.dispatchEvent(
                                new KeyboardEvent(ev.data.keyboardEvent.type, ev.data.keyboardEvent.options)
                            );
                        }
                    }
                    break;
                }
            }
        },
        // eslint-disable-next-line react-hooks/exhaustive-deps
        [shouldExpand, selectedViews, openViews, isWindows, activeProviderId, filters]
    );

    useEffect(() => {
        if (!searchMenuChannel.current) {
            const parentName = fin.me.name.replace(WindowName.BrowserAddressSearchPrefix, '');
            searchMenuChannel.current = new BroadcastChannel(`search-menu-${parentName}`);
            searchMenuChannel.current.postMessage({ type: 'ready' } as SearchMenuChannelResponse);
        }

        return () => {
            if (searchMenuChannel.current) {
                searchMenuChannel.current.close();
                searchMenuChannel.current = null;
            }
        };
    }, []);

    useEffect(() => {
        searchMenuChannel.current.onmessage = handleSearchMenuMessage;
    }, [handleSearchMenuMessage]);

    return {
        searchMenuChannel,
        selectedViews,
        openViews,
        queryId,
        updateSearchResults,
        searchQuery,
        hasTextChangedSinceExpansion
    };
};

export default useInitChannelToBrowserWindow;
