import { useCallback, useEffect, useRef } from 'react';

import styled from 'styled-components';

import { Box, Icon } from '@openfin/ui-library';

import { enterpriseSearchMenuTestIds } from '@common/utils/test-ids';
import { raiseBrowserAnalytics } from '@common/utils/usage-register';

import { t } from '@common/api/i18next';

import { SelectableResult } from '@enterprise/components/ControlBar/SearchMenu/ResultsContainerWrapper';

import { SiteIconWrapper } from './Icons';
import { SelectableResultContainer } from './Result';

interface ViewMoreResultsButtonProps {
    providerId: string;
    isFocused?: boolean;
    handleProviderSelected: (providerId: string) => void;
    onFocused: (result: SelectableResult) => void;
    providerTitle?: string;
}

const ViewMoreResultsButton: React.FC<ViewMoreResultsButtonProps> = ({
    providerId,
    isFocused,
    handleProviderSelected,
    onFocused,
    providerTitle
}) => {
    const containerRef = useRef<HTMLAnchorElement>(null);

    useEffect(() => {
        if (isFocused) {
            containerRef.current.focus({ preventScroll: true });
        }
    }, [isFocused]);

    const handleMouseDown = useCallback(() => {
        raiseBrowserAnalytics({
            type: 'Search',
            action: 'Select View More',
            value: providerTitle
        });
        handleProviderSelected(providerId);
    }, [handleProviderSelected, providerId, providerTitle]);

    //     The search menu uses visual focus tracking via the isFocused prop rather than relying solely on DOM focus. The Result component already handles Enter this way
    //   (document listener checking isFocused), but ViewMoreResultsButton was relying on the element having actual DOM focus - which may not always be the case when
    //   navigating with arrow keys while the search input retains focus.
    useEffect(() => {
        const handleKeyDown = (event: KeyboardEvent) => {
            if (isFocused && event.key === 'Enter') {
                event.preventDefault();
                event.stopPropagation();
                handleMouseDown();
            }
        };

        document.addEventListener('keydown', handleKeyDown);
        return () => document.removeEventListener('keydown', handleKeyDown);
    }, [isFocused, handleMouseDown]);

    return (
        <div className="search-result" role="listitem">
            <SelectableResultContainer
                role="option"
                as="a"
                tabIndex={0}
                ref={containerRef}
                onMouseDown={handleMouseDown}
                onFocus={() => onFocused({ type: 'view-more-result', id: `${providerId}-view-more`, providerId })}
                isSelected={isFocused}
                aria-live="polite"
                aria-label={t('enterpriseCommandBar.viewMore')}
                aria-selected={isFocused}
                data-testid={enterpriseSearchMenuTestIds.viewMoreResultsButton}
            >
                <SiteIconWrapper isSelected={isFocused}>
                    <Icon icon="DotsVerticalIcon" />
                </SiteIconWrapper>
                <ViewMoreText>{t('enterpriseCommandBar.viewMore')}</ViewMoreText>
            </SelectableResultContainer>
        </div>
    );
};

export default ViewMoreResultsButton;

const ViewMoreText = styled(Box)`
    display: flex;
    flex-direction: column;
    justify-content: center;
    min-width: 0;
`;
