import React, { FC, useCallback, useContext, useMemo } from 'react';

import styled from 'styled-components';

import { Text } from '@openfin/ui-library';

import { NoResults } from '@enterprise/components/ControlBar/SearchMenu/NoResults';
import { Result } from '@enterprise/components/ControlBar/SearchMenu/Result';
import {
    ResultsContainerWrapper,
    ViewMoreButton
} from '@enterprise/components/ControlBar/SearchMenu/ResultsContainerWrapper';
import { SkeletonResultList } from '@enterprise/components/ControlBar/SearchMenu/SkeletonResult';
import ViewMoreResultsButton from '@enterprise/components/ControlBar/SearchMenu/ViewMoreResultsButton';

import { SearchProvider, SearchProviderResult, SearchSitesResponse } from '@client-platform/shapes';
import { SearchMenuControlContext } from '@enterprise/context/SearchMenu/SearchMenuControlContext';
import { SearchResultsContext } from '@enterprise/context/SearchMenu/SearchResultsContext';
import { useAsyncProviderResults } from '@enterprise/hooks/EnterpriseSearchMenu/useAsyncProviderResults';
import { AsyncResultsObserver } from '@enterprise/hooks/EnterpriseSearchMenu/utils';

import { useAllProvidersAnnounceMessages } from './useAllProvidersAnnounceMessages';

const getFlattenedResultsWithViewMoreOptions = (asyncResults: SearchSitesResponse) => {
    return asyncResults
        .map((e) => {
            const res = e.results ?? [];
            return e.showViewMore
                ? [...res, { type: 'view-more-result', id: `${e.id}-view-more`, providerId: e.id } as ViewMoreButton]
                : res;
        })
        .flat();
};

const getSortedProviders = (providers: SearchProvider[]) => {
    // Results come in async but we should always display the suggestions first if any
    return [...providers].sort((a) => (a.title.includes('Suggestions') ? -1 : 0));
};

const getSortedProviderResults = (
    asyncResults: SearchSitesResponse,
    getProviderById: (id: string) => SearchProvider
) => {
    // Results come in async but we should always display the suggestions first if any
    const providers = asyncResults.map((provider) => getProviderById(provider.id)).filter((provider) => !!provider);
    return getSortedProviders(providers).map((provider) =>
        asyncResults.find((resultProvider) => resultProvider.id === provider.id)
    );
};

export const isContentLoading = (providerResults: SearchProviderResult): boolean => {
    return providerResults?.results === null || providerResults?.results === undefined;
};

interface AllResultsContainerProps {
    handleProviderSelected: (providerId: string) => void;
    asyncResultsObserver: AsyncResultsObserver;
}

export const AllProvidersResultsContainer: FC<AllResultsContainerProps> = ({
    handleProviderSelected,
    asyncResultsObserver
}) => {
    const {
        searchResults,
        searchProviders: rawSearchProviders,
        isQueryingResults,
        setAction
    } = useContext(SearchResultsContext);
    const { queryId } = useContext(SearchMenuControlContext);

    const searchProviders = useMemo(() => getSortedProviders(rawSearchProviders), [rawSearchProviders]);

    const asyncResults = useAsyncProviderResults(searchResults, asyncResultsObserver, queryId);
    const getProviderById = useCallback(
        (id: string) => searchProviders.find((provider) => provider.id === id),
        [searchProviders]
    );

    const isLoading = useMemo(() => {
        return isQueryingResults || asyncResults.some(isContentLoading);
    }, [isQueryingResults, asyncResults]);

    const hasNoResults = useMemo(() => {
        // Don't show "no results" if we haven't received any providers yet
        if (asyncResults.length === 0) {
            return false;
        }

        const allProvidersLoadedWithNoResults = asyncResults.every(
            (provider) =>
                !isContentLoading(provider) &&
                !provider.results?.length &&
                provider.results !== null &&
                provider.results !== undefined
        );

        return !isQueryingResults && !isLoading && allProvidersLoadedWithNoResults;
    }, [isQueryingResults, isLoading, asyncResults]);

    const sortedResults = useMemo(
        () => getSortedProviderResults(asyncResults, getProviderById),
        [asyncResults, getProviderById]
    );
    const flattenedResults = useMemo(() => getFlattenedResultsWithViewMoreOptions(sortedResults), [sortedResults]);

    useAllProvidersAnnounceMessages(flattenedResults, asyncResults);

    const renderProviderHeader = useCallback(
        (providerId: string) => (
            <Category className="search-results-category" data-is-header>
                <CategoryText className="search-results-category-text" size="base" as="h2">
                    {getProviderById(providerId)?.title}
                </CategoryText>
            </Category>
        ),
        [getProviderById]
    );

    const showSkeletons = isQueryingResults || asyncResults.length === 0;

    return (
        <ResultsContainerWrapper flattenedResults={flattenedResults} isLoading={isLoading}>
            {(setFocused, focused, onSiteAction) => (
                <>
                    {hasNoResults && <NoResults />}
                    {showSkeletons
                        ? searchProviders.map((provider) => (
                              <>
                                  {renderProviderHeader(provider.id)}
                                  <SkeletonResultList resultsNum={5} />
                              </>
                          ))
                        : sortedResults.map((providerResult) =>
                              !isContentLoading(providerResult) && providerResult.results.length === 0 ? null : (
                                  <>
                                      {renderProviderHeader(providerResult.id)}
                                      {isContentLoading(providerResult) ? (
                                          <SkeletonResultList resultsNum={5} />
                                      ) : (
                                          <>
                                              {providerResult.results.map((site) => (
                                                  <React.Fragment
                                                      key={`${providerResult.id}-section-${site.type}-${site.id}`}
                                                  >
                                                      <Result
                                                          site={site}
                                                          isFocused={site === focused}
                                                          id={`result-${site.type}-${site.id}`}
                                                          onSiteAction={onSiteAction}
                                                          onFocused={setFocused}
                                                          updateAction={setAction}
                                                      />
                                                  </React.Fragment>
                                              ))}
                                              {providerResult.showViewMore && (
                                                  <ViewMoreResultsButton
                                                      providerId={providerResult.id}
                                                      isFocused={focused?.id === `${providerResult.id}-view-more`}
                                                      handleProviderSelected={handleProviderSelected}
                                                      onFocused={setFocused}
                                                      providerTitle={getProviderById(providerResult.id)?.title}
                                                  />
                                              )}
                                          </>
                                      )}
                                  </>
                              )
                          )}
                </>
            )}
        </ResultsContainerWrapper>
    );
};

const Category = styled.div`
    margin-top: ${({ theme }) => theme.px.small};
`;

const CategoryText = styled(Text)`
    line-height: 15px;
    font-weight: 500;
    color: var(--color-enterprise-search-menu-text-soft);
    padding: ${({ theme }) => theme.px.xsmall};
    padding-left: ${({ theme }) => theme.px.small};
`;
