import React, {
    createContext,
    Dispatch,
    MutableRefObject,
    SetStateAction,
    useEffect,
    useMemo,
    useRef,
    useState
} from 'react';

import { OpenFin } from '@openfin/core';

import { SelectableResult } from '@common/utils/popup-window';
import { raiseBrowserAnalytics } from '@common/utils/usage-register';

import { ActionedSite, AttachedPage } from '@client-platform/index';
import useAdjustSearchMenuViewDimensions from '@enterprise/hooks/EnterpriseSearchMenu/AdjustSearchMenuDimensions/useAdjustSearchMenuViewDimensions';
import useInitChannelToBrowserWindow from '@enterprise/hooks/EnterpriseSearchMenu/useInitChannelToBrowserWindow';
import useOpenPages from '@enterprise/hooks/EnterpriseSearchMenu/useOpenPages';
import { usePostAnnounceMessagesToBrowserWindow } from '@enterprise/hooks/EnterpriseSearchMenu/usePostAnnounceMessagesToBrowserWindow';
import usePostMessageToBrowserWindow from '@enterprise/hooks/EnterpriseSearchMenu/usePostMessageToBrowserWindow';

import { SearchViewExpansionState } from './WindowSearchMenuContext';

const defaultFunction = async () => {
    return Promise.resolve();
};

interface SearchMenuControlContextType {
    containerRef: MutableRefObject<HTMLDivElement | null>;

    shouldExpandMenu: SearchViewExpansionState;
    shouldShowEmptySearchContainer: boolean;

    searchQuery: MutableRefObject<string>;
    hasTextChangedSinceExpansion: MutableRefObject<boolean>;
    focusRequestId: number | undefined;
    queryId: string;

    selectedViews: OpenFin.Identity[];
    openViews: OpenFin.Identity[];
    openPages: AttachedPage[];

    updateSearchResults: (params: {
        query: string;
        providerId: string;
        shouldExpandMenu?: SearchViewExpansionState;
        immediate?: boolean;
        searchFilters: string[];
    }) => Promise<void>;
    setSelectedSite: Dispatch<SetStateAction<ActionedSite | undefined>>;
    sendKeyboardEventToBrowserWindow: (event: React.KeyboardEvent) => void;
    postFocusedChangedAnnouncement: (focused: SelectableResult | null) => void;
    postAllProvidersAnnouncement: (message: string) => void;
    postSingleProviderAnnouncement: (message: string) => void;
}

export const SearchMenuControlContext = createContext<SearchMenuControlContextType>({
    containerRef: { current: null },

    shouldExpandMenu: { shouldExpand: false },
    shouldShowEmptySearchContainer: false,

    focusRequestId: undefined,
    searchQuery: { current: '' },
    hasTextChangedSinceExpansion: undefined,
    queryId: '',

    selectedViews: [],
    openViews: [],
    openPages: [],

    updateSearchResults: defaultFunction,
    setSelectedSite: defaultFunction,
    sendKeyboardEventToBrowserWindow: defaultFunction,
    postFocusedChangedAnnouncement: defaultFunction,
    postAllProvidersAnnouncement: defaultFunction,
    postSingleProviderAnnouncement: defaultFunction
});

export const SearchMenuControlContextProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const containerRef = useRef<HTMLDivElement>(null);

    const openPages = useOpenPages();

    const [shouldExpandMenu, setShouldExpandMenu] = useState<SearchViewExpansionState>({ shouldExpand: false });
    const [offsetLeft, setOffsetLeft] = useState<number>(0);
    const [shouldShowEmptySearchContainer, setShouldShowEmptySearchContainer] = useState(false);

    const [focusRequestId, setFocusRequestId] = useState<number>();
    const [selectedSite, setSelectedSite] = useState<ActionedSite | undefined>();

    useEffect(() => {
        if (selectedSite) {
            raiseBrowserAnalytics({
                action: 'Select Result',
                type: 'Search',
                value: selectedSite.title
            });
        }
    }, [selectedSite]);

    const {
        searchMenuChannel,
        selectedViews,
        openViews,
        queryId,
        updateSearchResults,
        searchQuery,
        hasTextChangedSinceExpansion
    } = useInitChannelToBrowserWindow(
        shouldExpandMenu.shouldExpand,
        setFocusRequestId,
        setShouldExpandMenu,
        setShouldShowEmptySearchContainer,
        setOffsetLeft,
        setSelectedSite
    );

    const { sendKeyboardEventToBrowserWindow } = usePostMessageToBrowserWindow(
        searchMenuChannel,
        selectedSite,
        selectedViews,
        shouldShowEmptySearchContainer,
        hasTextChangedSinceExpansion
    );

    const { postFocusedChangedAnnouncement, postAllProvidersAnnouncement, postSingleProviderAnnouncement } =
        usePostAnnounceMessagesToBrowserWindow(searchMenuChannel);

    useAdjustSearchMenuViewDimensions(
        containerRef,
        shouldExpandMenu.shouldExpand,
        searchMenuChannel,
        shouldShowEmptySearchContainer,
        offsetLeft
    );

    const value = useMemo(
        () => ({
            containerRef,
            shouldExpandMenu,
            shouldShowEmptySearchContainer,
            focusRequestId,
            searchQuery,
            hasTextChangedSinceExpansion,
            queryId,
            selectedViews,
            openViews,
            openPages,
            updateSearchResults,
            setSelectedSite,
            sendKeyboardEventToBrowserWindow,
            postFocusedChangedAnnouncement,
            postAllProvidersAnnouncement,
            postSingleProviderAnnouncement
        }),
        [
            shouldExpandMenu,
            shouldShowEmptySearchContainer,
            focusRequestId,
            queryId,
            selectedViews,
            openViews,
            openPages,
            updateSearchResults,
            sendKeyboardEventToBrowserWindow,
            postFocusedChangedAnnouncement,
            postAllProvidersAnnouncement,
            postSingleProviderAnnouncement
        ]
    );

    return <SearchMenuControlContext.Provider value={value}>{children}</SearchMenuControlContext.Provider>;
};
