import { Flag, flag } from '@common/api/flags';

type DebugData = Record<string, unknown> | undefined;

const isWorkspaceDebugEnabled = (): boolean => flag(Flag.DevDebug);

const formatDebugData = (data: DebugData): string =>
    Object.keys(data ?? {})
        .map((key) => `${key}: ${data?.[key]}`)
        .join(', ');

export const createInlineDebugLogger = (
    namespace: string
): ((event: string, data?: Record<string, unknown>) => void) => {
    return (event: string, data?: Record<string, unknown>) => {
        if (!isWorkspaceDebugEnabled()) {
            return;
        }

        const details = formatDebugData(data);
        const suffix = details ? `, ${details}` : '';
        console.log(`[${namespace}] ${Date.now()} ${event}${suffix}`);
    };
};
